import { useEffect, useMemo, useRef, useState, type ChangeEvent, type FormEvent, type ReactNode } from 'react'
import { Activity, ArrowDownLeft, ArrowRight, ArrowUpRight, Boxes, ChartNoAxesCombined, ChevronDown, Download, FileDown, FileSpreadsheet, FileUp, Landmark, LayoutDashboard, Menu, Package, Plus, Receipt, RotateCcw, Search, Settings2, ShieldCheck, SlidersHorizontal, Trash2, Truck, Wallet, X } from 'lucide-react'
import { addAudit, applyCleanStart, emptyStore, fromCents, loadStore, localDate, money, nextCode, numeric, round, saveStore, toCents, today, uid, vatCents, type Expense, type Product, type Sale, type StockMovement, type Store, type VehicleCompatibility } from './data'
import { activeExpenses, activePurchases, adjustStock, cancelSale, effectiveExpense, effectivePurchase, netPaid, netSale, periodReport, productProfitability, receivablesAging, registerImport, registerPayment, registerRefund, registerReturn, registerSale, registerStockCount, returnedQuantity, reviseExpense, revisePurchase, saleBalance, stockValuation, validDate } from './domain'
import { exportCatalog, exportExpenses, exportPurchases, exportSales, previewCatalog } from './files'
import { downloadBackup, readBackup } from './backup'

type Page = 'dashboard' | 'inventory' | 'sales' | 'imports' | 'expenses' | 'reports' | 'sri' | 'settings'
type Modal = 'product' | 'sale' | 'saleDetail' | 'payment' | 'refund' | 'return' | 'cancel' | 'import' | 'importDetail' | 'expense' | 'expenseDetail' | 'adjust' | 'confirm' | 'catalogPreview' | 'backupPreview' | 'editExpense' | 'editImport' | 'count' | null
type Period = '7d' | '30d' | '90d' | 'all' | 'custom'
type SaleItemDraft = { id: string; productId: string; quantity: string }
const nav: { id: Page; label: string; icon: typeof LayoutDashboard }[] = [
  { id: 'dashboard', label: 'Resumen', icon: LayoutDashboard },
  { id: 'inventory', label: 'Inventario', icon: Package },
  { id: 'sales', label: 'Ventas y cobros', icon: Receipt },
  { id: 'imports', label: 'Importaciones', icon: Truck },
  { id: 'expenses', label: 'Gastos', icon: Wallet },
  { id: 'reports', label: 'Reportes', icon: ChartNoAxesCombined },
  { id: 'sri', label: 'SRI', icon: Landmark },
  { id: 'settings', label: 'Configuración', icon: Settings2 },
]
const blankProduct = { name: '', category: '', brand: '', model: '', vehicle: '', partType: '', compatibility: '', stock: '0', minStock: '', cost: '', price: '' }
const blankSale = () => ({ customer: '', date: today(), vatRate: '15', paid: '0' })
const blankItem = (): SaleItemDraft => ({ id: uid(), productId: '', quantity: '1' })
function periodStart(period: Period) {
  if (period === 'all' || period === 'custom') return ''
  const date = new Date(); date.setDate(date.getDate() - Number(period.slice(0, -1)) + 1)
  return localDate(date)
}
function asNumber(text: string, label: string) {
  if (text.trim() === '' || !Number.isFinite(Number(text))) throw new Error(`${label}: ingresa un número válido.`)
  return Number(text)
}

type RemoteStore = { initial: Store; commit: (next: Store) => Promise<Store> }
function App({ remote }: { remote?: RemoteStore }) {
  const [store, setStore] = useState<Store>(() => remote?.initial ?? loadStore())
  useEffect(() => { if (remote) return; try { const clean = applyCleanStart(); if (clean) setStore(clean) } catch { setStore(emptyStore()) } }, [remote])
  const [page, setPage] = useState<Page>('dashboard')
  const [modal, setModal] = useState<Modal>(null)
  const [period, setPeriod] = useState<Period>('30d')
  const [customStart, setCustomStart] = useState(today())
  const [customEnd, setCustomEnd] = useState(today())
  const [revisionReason, setRevisionReason] = useState('')
  const [countReason, setCountReason] = useState('')
  const [countDate, setCountDate] = useState(today())
  const [countValues, setCountValues] = useState<Record<string, string>>({})
  const [compatRows, setCompatRows] = useState<VehicleCompatibility[]>([])
  const [profitSort, setProfitSort] = useState<'profit' | 'margin' | 'units'>('profit')
  const [query, setQuery] = useState('')
  const [mobileNav, setMobileNav] = useState(false)
  const [toast, setToast] = useState('')
  const [editingProductId, setEditingProductId] = useState<string | null>(null)
  const [selectedProductId, setSelectedProductId] = useState<string | null>(null)
  const [selectedSaleId, setSelectedSaleId] = useState<string | null>(null)
  const [selectedImportId, setSelectedImportId] = useState<string | null>(null)
  const [selectedExpenseId, setSelectedExpenseId] = useState<string | null>(null)
  const [productForm, setProductForm] = useState(blankProduct)
  const [saleForm, setSaleForm] = useState(blankSale)
  const [saleItems, setSaleItems] = useState<SaleItemDraft[]>([blankItem()])
  const [paymentForm, setPaymentForm] = useState({ amount: '', method: 'Transferencia', date: today() })
  const [refundForm, setRefundForm] = useState({ amount: '', method: 'Transferencia', date: today(), reason: '' })
  const [returnForm, setReturnForm] = useState({ lineId: '', quantity: '1', date: today(), reason: '' })
  const [cancelForm, setCancelForm] = useState({ date: today(), reason: '' })
  const [importForm, setImportForm] = useState({ supplier: '', productId: '', quantity: '1', unitCost: '', date: today() })
  const [expenseForm, setExpenseForm] = useState({ category: '', description: '', amount: '', date: today() })
  const [adjustForm, setAdjustForm] = useState({ stock: '', reason: '' })
  const [catalogPreview, setCatalogPreview] = useState<{ filename: string; products: Product[] } | null>(null)
  const [backupPreview, setBackupPreview] = useState<Store | null>(null)
  const [confirmAction, setConfirmAction] = useState<{ title: string; detail: string; run: () => void } | null>(null)
  const [confirmChecks, setConfirmChecks] = useState([false, false, false])
  const catalogInput = useRef<HTMLInputElement>(null)
  const backupInput = useRef<HTMLInputElement>(null)

  function notify(message: string) { setToast(message); window.setTimeout(() => setToast(''), 5000) }
  function commit(next: Store, message: string) {
    if (remote) {
      remote.commit(next).then(saved => { setStore(saved); setModal(null); notify(message) })
        .catch(error => notify(error instanceof Error ? error.message : 'No se pudo guardar la operación.'))
      return
    }
    try { saveStore(next); setStore(next); setModal(null); notify(message) }
    catch { notify('No se pudo guardar. Descarga un respaldo y revisa el espacio disponible del navegador.') }
  }
  function attempt(run: () => Store, message: string) { try { commit(run(), message) } catch (error) { notify(error instanceof Error ? error.message : 'No se pudo completar la operación.') } }
  function requestConfirm(title: string, detail: string, run: () => void) { setConfirmAction({ title, detail, run }); setConfirmChecks([false, false, false]); setModal('confirm') }
  function switchPage(next: Page) { if (remote && next === 'settings') { notify('La configuración local no está disponible en la edición compartida.'); return }; setPage(next); setQuery(''); setMobileNav(false) }

  const start = period === 'custom' ? customStart : periodStart(period)
  const end = period === 'custom' ? customEnd : ''
  const report = useMemo(() => periodReport(store, start, end), [store, start, end])
  const profitRows = useMemo(() => productProfitability(store, start, end).sort((a, b) => profitSort === 'units' ? b.units - a.units : profitSort === 'margin' ? (b.revenue > 0 ? b.profit / b.revenue : -Infinity) - (a.revenue > 0 ? a.profit / a.revenue : -Infinity) : b.profit - a.profit), [store, start, end, profitSort])
  const aging = useMemo(() => receivablesAging(store, today()), [store])
  const valuation = useMemo(() => stockValuation(store), [store])
  const expensesNow = activeExpenses(store)
  const purchasesNow = activePurchases(store)
  const pending = round(store.sales.reduce((sum, sale) => sum + Math.max(0, saleBalance(store, sale)), 0))
  const refundDue = round(store.sales.reduce((sum, sale) => sum + Math.max(0, -saleBalance(store, sale)), 0))
  const lowStock = store.products.filter(p => p.active && p.minStock !== null && p.stock <= p.minStock)
  const activeProducts = store.products.filter(p => p.active)
  const filteredProducts = store.products.filter(p => [p.code, p.name, p.category, p.brand, p.model, p.vehicle, p.partType, p.compatibility, ...(p.compatibilities ?? []).flatMap(c => [c.brand, c.model, c.engine, c.notes, String(c.yearFrom ?? ''), String(c.yearTo ?? '')])].join(' ').toLocaleLowerCase('es').includes(query.toLocaleLowerCase('es')))
  const filteredSales = store.sales.filter(s => [s.number, s.customer, ...s.lines.flatMap(line => [line.productCode, line.productName])].join(' ').toLocaleLowerCase('es').includes(query.toLocaleLowerCase('es')))
  const selectedProduct = store.products.find(p => p.id === selectedProductId)
  const selectedSale = store.sales.find(s => s.id === selectedSaleId)
  const selectedImportOriginal = store.purchases.find(p => p.id === selectedImportId)
  const selectedExpenseOriginal = store.expenses.find(e => e.id === selectedExpenseId)
  const selectedImport = selectedImportOriginal && (effectivePurchase(store, selectedImportOriginal) ?? selectedImportOriginal)
  const selectedExpense = selectedExpenseOriginal && (effectiveExpense(store, selectedExpenseOriginal) ?? selectedExpenseOriginal)
  const selectedImportVoided = !!selectedImportOriginal && !effectivePurchase(store, selectedImportOriginal)
  const selectedExpenseVoided = !!selectedExpenseOriginal && !effectiveExpense(store, selectedExpenseOriginal)
  const currentTitle = nav.find(item => item.id === page)?.label ?? ''
  const periodPicker = <select className="period-select" value={period} onChange={e => setPeriod(e.target.value as Period)} aria-label="Período"><option value="7d">Últimos 7 días</option><option value="30d">Últimos 30 días</option><option value="90d">Últimos 90 días</option><option value="all">Todo el período</option><option value="custom">Fechas personalizadas</option></select>

  function openProduct(product?: Product) {
    setEditingProductId(product?.id ?? null)
    setCompatRows(product?.compatibilities ?? [])
    setProductForm(product ? { name: product.name, category: product.category, brand: product.brand, model: product.model, vehicle: product.vehicle, partType: product.partType, compatibility: product.compatibility, stock: String(product.stock), minStock: product.minStock === null ? '' : String(product.minStock), cost: String(product.cost), price: String(product.price) } : blankProduct)
    setModal('product')
  }
  function saveProduct(event: FormEvent) {
    event.preventDefault()
    try {
      const old = store.products.find(p => p.id === editingProductId)
      const stock = asNumber(productForm.stock, 'Stock'), cost = asNumber(productForm.cost, 'Costo'), price = asNumber(productForm.price, 'Precio')
      const minStock = productForm.minStock.trim() === '' ? null : asNumber(productForm.minStock, 'Stock mínimo')
      if (!productForm.name.trim() || !Number.isSafeInteger(stock) || stock < 0 || cost < 0 || price < 0 || Math.abs(cost * 100 - Math.round(cost * 100)) > 0.000001 || Math.abs(price * 100 - Math.round(price * 100)) > 0.000001 || minStock !== null && (!Number.isSafeInteger(minStock) || minStock < 0)) throw new Error('Revisa nombre, stock, costo y precio. Los importes admiten máximo dos decimales.')
      for (const c of compatRows) { if (!c.brand.trim() || !c.model.trim() || c.yearFrom !== null && (!Number.isSafeInteger(c.yearFrom) || c.yearFrom < 1900) || c.yearTo !== null && (!Number.isSafeInteger(c.yearTo) || c.yearTo < (c.yearFrom ?? 1900))) throw new Error('Revisa marca, modelo y años de cada compatibilidad.') }
      const product: Product = { id: old?.id ?? uid(), code: old?.code ?? nextCode(store.products), name: productForm.name.trim(), category: productForm.category.trim(), brand: productForm.brand.trim(), model: productForm.model.trim(), vehicle: productForm.vehicle.trim(), partType: productForm.partType.trim(), compatibility: productForm.compatibility.trim(), stock: old?.stock ?? stock, minStock, cost: round(cost), price: round(price), active: old?.active ?? true, compatibilities: compatRows }
      const apply = () => {
        const products = old ? store.products.map(p => p.id === old.id ? product : p) : [...store.products, product]
        const stockMovements = !old && stock > 0 ? [{ id: uid(), date: today(), productId: product.id, productCode: product.code, delta: stock, balanceAfter: stock, reason: 'Stock inicial', source: 'initial' as const }, ...store.stockMovements] : store.stockMovements
        const detail = old ? `${product.code}: costo ${money(old.cost)} → ${money(product.cost)}; precio ${money(old.price)} → ${money(product.price)}` : `${product.code}: ${product.name}, stock inicial ${stock}`
        commit(addAudit({ ...store, products, stockMovements }, old ? 'Producto editado' : 'Producto creado', detail), old ? 'Producto actualizado' : 'Producto creado')
      }
      if (old) requestConfirm('Confirmar edición', `${product.code} · ${product.name}. Las ventas anteriores conservan sus importes.`, apply)
      else apply()
    } catch (error) { notify(error instanceof Error ? error.message : 'No se pudo guardar el producto.') }
  }
  function archiveProduct(product: Product) { requestConfirm('Archivar producto', `${product.code} · ${product.name}. Permanecerá en el historial.`, () => commit(addAudit({ ...store, products: store.products.map(p => p.id === product.id ? { ...p, active: false } : p) }, 'Producto archivado', `${product.code}: ${product.name}`), 'Producto archivado')) }
  function saveAdjustment(event: FormEvent) {
    event.preventDefault(); if (!selectedProduct) return
    try {
      const next = adjustStock(store, selectedProduct.id, asNumber(adjustForm.stock, 'Nuevo stock'), adjustForm.reason, today())
      requestConfirm('Confirmar ajuste de stock', `${selectedProduct.code}: ${selectedProduct.stock} → ${adjustForm.stock}. Motivo: ${adjustForm.reason.trim()}`, () => commit(next, 'Stock ajustado'))
    } catch (error) { notify(error instanceof Error ? error.message : 'Ajuste inválido.') }
  }
  function openSale() { setSaleForm(blankSale()); setSaleItems([blankItem()]); setModal('sale') }
  function saveSale(event: FormEvent) {
    event.preventDefault()
    attempt(() => registerSale(store, { customer: saleForm.customer, date: saleForm.date, vatRate: asNumber(saleForm.vatRate, 'IVA') / 100, paid: asNumber(saleForm.paid, 'Cobro inicial'), items: saleItems.map(item => ({ productId: item.productId, quantity: asNumber(item.quantity, 'Cantidad') })) }), 'Venta registrada')
  }
  function openPayment(sale: Sale) { setSelectedSaleId(sale.id); setPaymentForm({ amount: String(Math.max(0, saleBalance(store, sale))), method: 'Transferencia', date: today() }); setModal('payment') }
  function savePayment(event: FormEvent) { event.preventDefault(); if (!selectedSale) return; attempt(() => registerPayment(store, selectedSale.id, asNumber(paymentForm.amount, 'Cobro'), paymentForm.method, paymentForm.date), 'Cobro registrado') }
  function openRefund(sale: Sale) { setSelectedSaleId(sale.id); setRefundForm({ amount: String(Math.max(0, -saleBalance(store, sale))), method: 'Transferencia', date: today(), reason: '' }); setModal('refund') }
  function saveRefund(event: FormEvent) { event.preventDefault(); if (!selectedSale) return; attempt(() => registerRefund(store, selectedSale.id, asNumber(refundForm.amount, 'Reembolso'), refundForm.method, refundForm.date, refundForm.reason), 'Reembolso registrado') }
  function openReturn(sale: Sale) { setSelectedSaleId(sale.id); setReturnForm({ lineId: sale.lines.find(line => line.quantity > returnedQuantity(store, line.id))?.id ?? '', quantity: '1', date: today(), reason: '' }); setModal('return') }
  function saveReturn(event: FormEvent) { event.preventDefault(); if (!selectedSale) return; attempt(() => registerReturn(store, selectedSale.id, returnForm.lineId, asNumber(returnForm.quantity, 'Cantidad'), returnForm.date, returnForm.reason), 'Devolución registrada') }
  function openCancel(sale: Sale) { setSelectedSaleId(sale.id); setCancelForm({ date: today(), reason: '' }); setModal('cancel') }
  function saveCancel(event: FormEvent) {
    event.preventDefault(); if (!selectedSale) return
    try {
      const next = cancelSale(store, selectedSale.id, cancelForm.date, cancelForm.reason)
      requestConfirm('Confirmar anulación', `${selectedSale.number}: se devolverán al stock las piezas restantes. Los cobros quedarán pendientes de reembolso. Motivo: ${cancelForm.reason.trim()}`, () => commit(next, 'Venta anulada'))
    } catch (error) { notify(error instanceof Error ? error.message : 'No se pudo anular.') }
  }
  function openImport() { setImportForm({ supplier: '', productId: '', quantity: '1', unitCost: '', date: today() }); setModal('import') }
  function saveImport(event: FormEvent) { event.preventDefault(); attempt(() => registerImport(store, importForm.productId, asNumber(importForm.quantity, 'Cantidad'), asNumber(importForm.unitCost, 'Costo'), importForm.supplier, importForm.date), 'Entrada registrada') }
  function saveExpense(event: FormEvent) {
    event.preventDefault()
    try {
      const amount = asNumber(expenseForm.amount, 'Monto')
      if (!validDate(expenseForm.date) || !expenseForm.category.trim() || !expenseForm.description.trim() || amount <= 0 || round(amount) !== amount) throw new Error('Revisa fecha, categoría, descripción y monto.')
      const expense: Expense = { id: uid(), date: expenseForm.date, category: expenseForm.category.trim(), description: expenseForm.description.trim(), amount }
      commit(addAudit({ ...store, expenses: [expense, ...store.expenses] }, 'Gasto registrado', `${expense.category}: ${expense.description}, ${money(amount)}`), 'Gasto registrado')
    } catch (error) { notify(error instanceof Error ? error.message : 'Gasto inválido.') }
  }
  function openEditExpense() {
    if (!selectedExpense) return
    setExpenseForm({ date: selectedExpense.date, category: selectedExpense.category, description: selectedExpense.description, amount: String(selectedExpense.amount) })
    setRevisionReason(''); setModal('editExpense')
  }
  function saveExpenseRevision(event: FormEvent) {
    event.preventDefault(); if (!selectedExpense) return
    try {
      const after: Expense = { ...selectedExpense, date: expenseForm.date, category: expenseForm.category.trim(), description: expenseForm.description.trim(), amount: asNumber(expenseForm.amount, 'Monto') }
      const next = reviseExpense(store, selectedExpense.id, after, revisionReason)
      requestConfirm('Confirmar corrección', `Gasto ${selectedExpense.description}: ${money(selectedExpense.amount)} → ${money(after.amount)}. Motivo: ${revisionReason}`, () => commit(next, 'Gasto corregido'))
    } catch (error) { notify(error instanceof Error ? error.message : 'Corrección inválida.') }
  }
  function voidExpense() {
    if (!selectedExpense) return
    try { const next = reviseExpense(store, selectedExpense.id, null, revisionReason); requestConfirm('Anular gasto', `El gasto ${selectedExpense.description} dejará de sumar en reportes. Motivo: ${revisionReason}`, () => commit(next, 'Gasto anulado')) }
    catch (error) { notify(error instanceof Error ? error.message : 'No se pudo anular.') }
  }
  function openEditImport() {
    if (!selectedImport) return
    setImportForm({ date: selectedImport.date, supplier: selectedImport.supplier, productId: selectedImport.productId, quantity: String(selectedImport.quantity), unitCost: String(selectedImport.unitCost) })
    setRevisionReason(''); setModal('editImport')
  }
  function saveImportRevision(event: FormEvent) {
    event.preventDefault(); if (!selectedImport) return
    try {
      const quantity = asNumber(importForm.quantity, 'Cantidad'), unitCost = asNumber(importForm.unitCost, 'Costo')
      const after = { ...selectedImport, date: importForm.date, supplier: importForm.supplier.trim(), quantity, unitCost, total: fromCents(quantity * toCents(unitCost)) }
      const next = revisePurchase(store, selectedImport.id, after, revisionReason)
      requestConfirm('Confirmar corrección', `${selectedImport.productCode}: ${selectedImport.quantity} → ${quantity} unidades. Motivo: ${revisionReason}`, () => commit(next, 'Entrada corregida'))
    } catch (error) { notify(error instanceof Error ? error.message : 'Corrección inválida.') }
  }
  function voidImport() {
    if (!selectedImport) return
    try { const next = revisePurchase(store, selectedImport.id, null, revisionReason); requestConfirm('Anular entrada', `${selectedImport.productCode}: se restarán ${selectedImport.quantity} unidades. Motivo: ${revisionReason}`, () => commit(next, 'Entrada anulada')) }
    catch (error) { notify(error instanceof Error ? error.message : 'No se pudo anular.') }
  }
  function openCount() { setCountReason(''); setCountDate(today()); setCountValues({}); setModal('count') }
  function saveCount(event: FormEvent) {
    event.preventDefault()
    try {
      const entries = Object.entries(countValues).filter(([, value]) => value.trim() !== '').map(([productId, value]) => ({ productId, counted: asNumber(value, 'Conteo') }))
      const next = registerStockCount(store, entries, countReason, countDate)
      const differences = next.stockCounts[0].lines.filter(line => line.expected !== line.counted).length
      requestConfirm('Confirmar conteo', `${entries.length} productos contados; ${differences} diferencias. Motivo: ${countReason}`, () => commit(next, 'Conteo registrado'))
    } catch (error) { notify(error instanceof Error ? error.message : 'Conteo inválido.') }
  }
  async function importCatalog(event: ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0]; if (!file) return
    try { setCatalogPreview(await previewCatalog(file, store.products)); setModal('catalogPreview') }
    catch (error) { notify(error instanceof Error ? error.message : 'No se pudo leer el archivo.') }
    finally { if (catalogInput.current) catalogInput.current.value = '' }
  }
  function confirmCatalog() {
    if (!catalogPreview) return
    const stockMovements: StockMovement[] = catalogPreview.products.filter(p => p.stock > 0).map(p => ({ id: uid(), date: today(), productId: p.id, productCode: p.code, delta: p.stock, balanceAfter: p.stock, reason: `Importación de catálogo: ${catalogPreview.filename}`, source: 'initial' }))
    commit(addAudit({ ...store, products: [...store.products, ...catalogPreview.products], stockMovements: [...stockMovements, ...store.stockMovements] }, 'Catálogo importado', `${catalogPreview.products.length} productos desde ${catalogPreview.filename}`), `${catalogPreview.products.length} productos agregados`)
    setCatalogPreview(null)
  }
  async function importBackup(event: ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0]; if (!file) return
    try { setBackupPreview(await readBackup(file)); setModal('backupPreview') }
    catch (error) { notify(error instanceof Error ? error.message : 'No se pudo leer el respaldo.') }
    finally { if (backupInput.current) backupInput.current.value = '' }
  }
  function confirmBackup() {
    if (!backupPreview) return
    const next = backupPreview
    requestConfirm('Restaurar respaldo', `Se reemplazarán los datos actuales de este navegador por ${next.products.length} productos y ${next.sales.length} ventas del respaldo.`, () => commit(next, 'Respaldo restaurado'))
  }
  function clearAll() { requestConfirm('Borrar datos locales', 'Se borrarán los datos de este navegador. Descarga un respaldo antes si quieres conservarlos.', () => commit(emptyStore(), 'Datos locales borrados')) }

  const previewLineCents = saleItems.map(item => { const product = activeProducts.find(p => p.id === item.productId), quantity = Number(item.quantity); const cents = product && Number.isSafeInteger(quantity) && quantity > 0 && quantity <= product.stock ? toCents(product.price) * quantity : 0; return Number.isSafeInteger(cents) ? cents : 0 })
  const saleSubtotalPreview = fromCents(previewLineCents.reduce((sum, cents) => sum + cents, 0))
  const previewRate = Math.min(1, Math.max(0, Number(saleForm.vatRate) / 100 || 0))
  const saleVatPreview = fromCents(previewLineCents.reduce((sum, cents) => sum + vatCents(cents, previewRate), 0))

  return <div className="app-shell">
    <aside className={`sidebar ${mobileNav ? 'sidebar-open' : ''}`}>
      <div className="brand"><div className="brand-wordmark"><strong>TORQUEX</strong><small>Control de repuestos</small></div><button className="mobile-close" aria-label="Cerrar menú" onClick={() => setMobileNav(false)}><X size={20} /></button></div>
      <div className="sidebar-label">Espacio de trabajo</div>
      <nav aria-label="Navegación principal">{nav.map(item => <button key={item.id} className={`nav-item ${page === item.id ? 'active' : ''}`} onClick={() => switchPage(item.id)}><item.icon size={19} strokeWidth={1.8} /><span>{item.label}</span>{page === item.id && <span className="nav-indicator" />}</button>)}</nav>
      <div className="sidebar-bottom"><div className="demo-status"><span className="status-dot" /><div><strong>Modo prototipo</strong><small>Prueba con datos ficticios</small></div></div><p>Esta versión guarda información solo en este navegador.</p></div>
    </aside>
    {mobileNav && <button className="mobile-scrim" aria-label="Cerrar menú" onClick={() => setMobileNav(false)} />}
    <main className="main-content">
      <header className="topbar"><div className="topbar-left"><button className="menu-toggle" aria-label="Abrir menú" onClick={() => setMobileNav(true)}><Menu size={22} /></button><span className="breadcrumb">Torquex</span><span className="breadcrumb-sep">/</span><strong>{currentTitle}</strong></div><div className="topbar-right"><span className="topbar-date">{new Intl.DateTimeFormat('es-EC', { day: 'numeric', month: 'long', year: 'numeric' }).format(new Date())}</span><span className="avatar">TX</span></div></header>
      <div className="page-content">
        {page === 'dashboard' && <>
          <PageHeading eyebrow="Panel de operaciones" title="Todo bajo control." subtitle="Una vista clara de ventas, inventario y dinero pendiente." actions={<>{periodPicker}<button className="button button-primary" onClick={openSale}><Plus size={17} /> Nueva venta</button></>} />
          
          <div className="metric-grid">
            <Metric label="Ventas netas sin IVA" value={money(report.subtotal)} detail={`${report.salesCount} ventas · ${report.returnsCount} devoluciones`} icon={<ArrowUpRight size={20} />} accent="blue" />
            <Metric label="Cobrado neto" value={money(report.collected)} detail="Cobros menos reembolsos del período" icon={<ArrowDownLeft size={20} />} accent="dark" />
            <Metric label="Cuentas por cobrar" value={money(pending)} detail="Saldo de todas las ventas" icon={<Wallet size={20} />} accent="orange" />
            <Metric label="Resultado operativo" value={money(report.operatingResult)} detail="Ventas − costo vendido − gastos" icon={<Activity size={20} />} accent="plain" />
          </div>
          {refundDue > 0 && <div className="refund-banner"><RotateCcw size={17} /> Hay {money(refundDue)} pendientes de reembolso. <button onClick={() => switchPage('sales')}>Ver ventas <ArrowRight size={15} /></button></div>}
          <div className="dashboard-grid"><section className="panel"><div className="panel-head"><div><h2>Movimientos recientes</h2><p>{remote ? "Actividad compartida del equipo" : "Actividad registrada en este navegador"}</p></div><button className="text-link" onClick={() => switchPage('reports')}>Ver reportes <ArrowRight size={16} /></button></div><div className="activity-list">{store.audit.slice(0, 5).map(a => <div className="activity-row" key={a.id}><div className="activity-icon"><Activity size={17} /></div><div className="activity-copy"><strong>{a.action}</strong><span>{a.detail}{a.actorName ? ` · ${a.actorName}` : ""}</span></div><time>{new Intl.DateTimeFormat('es-EC', { day: '2-digit', month: 'short' }).format(new Date(a.date))}</time></div>)}{store.audit.length === 0 && <Empty text="Aún no hay movimientos." />}</div></section><section className="panel"><div className="panel-head"><div><h2>Atención de inventario</h2><p>Productos que necesitan revisión</p></div><span className="count-pill">{lowStock.length}</span></div>{lowStock.slice(0, 4).map(p => <div className="stock-row" key={p.id}><div><strong>{p.name}</strong><span>{p.code} · {p.brand}</span></div><div className="stock-amount"><strong>{p.stock}</strong><span>mín. {p.minStock}</span></div></div>)}{lowStock.length === 0 && <Empty text="No hay productos bajo el stock mínimo." />}<button className="panel-footer-link" onClick={() => switchPage('inventory')}>Abrir inventario <ArrowRight size={17} /></button></section></div>
          <div className="quick-grid"><QuickAction icon={<Boxes size={20} />} title="Agregar producto" detail="Crear ficha con código automático" onClick={() => openProduct()} /><QuickAction icon={<Truck size={20} />} title="Registrar importación" detail="Actualizar existencias y costo" onClick={openImport} /><QuickAction icon={<Receipt size={20} />} title="Registrar gasto" detail="Clasificar un egreso operativo" onClick={() => { setExpenseForm({ category: '', description: '', amount: '', date: today() }); setModal('expense') }} /></div>
        </>}

        {page === 'inventory' && <>
          <PageHeading eyebrow="Catálogo y existencias" title="Inventario" subtitle={`${activeProducts.length} productos activos · ${lowStock.length} con stock bajo`} actions={<><input ref={catalogInput} className="hidden-input" type="file" accept=".csv,.xlsx" onChange={importCatalog} /><button className="button button-outline" onClick={() => catalogInput.current?.click()}><FileUp size={17} /> Importar</button><button className="button button-outline" onClick={() => exportCatalog(store, 'csv')}><Download size={17} /> CSV</button><button className="button button-outline" onClick={() => exportCatalog(store, 'xlsx')}><FileSpreadsheet size={17} /> Excel</button><button className="button button-outline" onClick={openCount}><Boxes size={17} /> Conteo</button><button className="button button-primary" onClick={() => openProduct()}><Plus size={17} /> Nuevo producto</button></>} />
          <div className="toolbar"><div className="search-wrap"><Search size={18} /><input aria-label="Buscar productos" value={query} onChange={e => setQuery(e.target.value)} placeholder="Buscar código, pieza, marca o vehículo" /></div><span className="toolbar-note"><SlidersHorizontal size={17} /> Códigos automáticos</span></div>
          <div className="panel table-panel"><div className="table-scroll"><table><thead><tr><th>Producto</th><th>Compatibilidad</th><th>Stock</th><th>Costo</th><th>Precio</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>{filteredProducts.map(p => <tr key={p.id}><td><div className="product-cell"><div className="product-icon"><Package size={19} /></div><div><strong>{p.name}</strong><small>{p.code} · {p.brand} {p.model}</small></div></div></td><td><div className="two-line"><strong>{p.compatibilities?.length ? `${p.compatibilities[0].brand} ${p.compatibilities[0].model}` : p.vehicle || 'Sin vehículo'}</strong><small>{p.compatibilities?.length ? `${p.compatibilities[0].engine} ${p.compatibilities[0].yearFrom ?? ''}–${p.compatibilities[0].yearTo ?? ''}` : p.compatibility.split(/\r?\n/)[0] || p.partType || 'Sin compatibilidad'}{(p.compatibilities?.length ?? 0) > 1 ? ` +${(p.compatibilities?.length ?? 0) - 1} más` : ''}</small></div></td><td><strong>{numeric(p.stock)}</strong>{p.minStock !== null && <small className="cell-sub">Mín. {p.minStock}</small>}</td><td>{money(p.cost)}</td><td className="bold-cell">{money(p.price)}</td><td><span className={`badge ${!p.active ? 'badge-muted' : p.minStock !== null && p.stock <= p.minStock ? 'badge-warning' : 'badge-ok'}`}>{!p.active ? 'Archivado' : p.minStock !== null && p.stock <= p.minStock ? 'Stock bajo' : 'Disponible'}</span></td><td><div className="row-actions"><button onClick={() => openProduct(p)}>Editar</button>{p.active && <button onClick={() => { setSelectedProductId(p.id); setAdjustForm({ stock: String(p.stock), reason: '' }); setModal('adjust') }}>Ajustar</button>}{p.active && <button className="danger-link" aria-label={`Archivar ${p.name}`} onClick={() => archiveProduct(p)}><Trash2 size={16} /></button>}</div></td></tr>)}</tbody></table></div>{filteredProducts.length === 0 && <Empty text="No se encontraron productos." />}</div><p className="helper-line">CSV y Excel agregan productos nuevos después de una vista previa. No reemplazan registros existentes.</p>
        </>}

        {page === 'sales' && <>
          <PageHeading eyebrow="Movimientos comerciales" title="Ventas y cobros" subtitle="Ventas, devoluciones, cobros y reembolsos conservan su historial." actions={<button className="button button-primary" onClick={openSale}><Plus size={17} /> Nueva venta</button>} />
          <div className="mini-metrics"><MiniMetric label="Ventas netas con IVA" value={money(round(store.sales.reduce((sum, sale) => sum + netSale(store, sale).total, 0)))} /><MiniMetric label="Por cobrar" value={money(pending)} /><MiniMetric label="Por reembolsar" value={money(refundDue)} /></div>
          <div className="toolbar"><div className="search-wrap"><Search size={18} /><input aria-label="Buscar ventas" value={query} onChange={e => setQuery(e.target.value)} placeholder="Buscar venta, cliente o producto" /></div></div>
          <div className="panel table-panel"><div className="table-scroll"><table><thead><tr><th>Venta</th><th>Cliente / piezas</th><th>Original</th><th>Neto actual</th><th>Estado</th><th>Saldo</th><th>Acción</th></tr></thead><tbody>{filteredSales.map(sale => { const balance = saleBalance(store, sale), net = netSale(store, sale); return <tr key={sale.id}><td><strong>{sale.number}</strong><small className="cell-sub">{sale.date}{sale.createdByName ? ` · ${sale.createdByName}` : ""}</small></td><td><div className="two-line"><strong>{sale.customer}</strong><small>{sale.lines.map(line => `${line.quantity} × ${line.productName}`).join(' · ')}</small></div></td><td>{money(sale.total)}</td><td className="bold-cell">{money(net.total)}</td><td><span className={`badge ${sale.status === 'cancelled' ? 'badge-muted' : store.returns.some(item => item.saleId === sale.id) ? 'badge-warning' : 'badge-ok'}`}>{sale.status === 'cancelled' ? 'Anulada' : store.returns.some(item => item.saleId === sale.id) ? 'Con devolución' : 'Activa'}</span></td><td>{balance > 0 ? <span className="badge badge-warning">Por cobrar {money(balance)}</span> : balance < 0 ? <span className="badge badge-warning">Reembolsar {money(-balance)}</span> : <span className="badge badge-ok">Al día</span>}</td><td><button className="table-action" onClick={() => { setSelectedSaleId(sale.id); setModal('saleDetail') }}>Ver detalle</button></td></tr> })}</tbody></table></div>{filteredSales.length === 0 && <Empty text="No hay ventas. Registra una para empezar." />}</div>
        </>}

        {page === 'imports' && <>
          <PageHeading eyebrow="Entradas de mercadería" title="Importaciones" subtitle="Cada entrada conserva proveedor, cantidad y costo del momento." actions={<><button className="button button-outline" onClick={() => exportPurchases(store, 'csv')}>CSV</button><button className="button button-outline" onClick={() => exportPurchases(store, 'xlsx')}>Excel</button><button className="button button-primary" onClick={openImport}><Plus size={17} /> Nueva entrada</button></>} />
          <div className="mini-metrics"><MiniMetric label="Entradas registradas" value={String(store.purchases.length)} /><MiniMetric label="Unidades recibidas" value={numeric(purchasesNow.reduce((sum, p) => sum + p.quantity, 0))} /><MiniMetric label="Costo registrado" value={money(purchasesNow.reduce((sum, p) => sum + p.total, 0))} /></div>
          <div className="panel table-panel"><div className="table-scroll"><table><thead><tr><th>Fecha</th><th>Proveedor</th><th>Producto</th><th>Unidades</th><th>Costo unitario</th><th>Total</th><th></th></tr></thead><tbody>{store.purchases.map(original => { const p = effectivePurchase(store, original) ?? original; const voided = !effectivePurchase(store, original); return <tr key={p.id}><td>{p.date}</td><td><strong>{p.supplier}</strong><small className="cell-sub">{p.createdByName ?? ""}</small></td><td><div className="two-line"><strong>{p.productName}</strong><small>{p.productCode}</small></div></td><td>{voided ? "Anulada" : p.quantity}</td><td>{money(p.unitCost)}</td><td className="bold-cell">{money(voided ? 0 : p.total)}</td><td><button className="table-action" onClick={() => { setSelectedImportId(p.id); setModal('importDetail') }}>Ver detalle</button></td></tr> })}</tbody></table></div>{store.purchases.length === 0 && <Empty text="Aún no hay entradas registradas." />}</div>
        </>}

        {page === 'expenses' && <>
          <PageHeading eyebrow="Egresos operativos" title="Gastos" subtitle="Registra por qué salió dinero y consulta cada gasto en su ficha." actions={<><button className="button button-outline" onClick={() => exportExpenses(store, 'csv')}>CSV</button><button className="button button-outline" onClick={() => exportExpenses(store, 'xlsx')}>Excel</button><button className="button button-primary" onClick={() => { setExpenseForm({ category: '', description: '', amount: '', date: today() }); setModal('expense') }}><Plus size={17} /> Nuevo gasto</button></>} />
          <div className="mini-metrics"><MiniMetric label="Total de gastos" value={money(expensesNow.reduce((sum, e) => sum + e.amount, 0))} /><MiniMetric label="Registros" value={String(store.expenses.length)} /><MiniMetric label="Categorías" value={String(new Set(expensesNow.map(e => e.category)).size)} /></div>
          <div className="panel table-panel"><div className="table-scroll"><table><thead><tr><th>Fecha</th><th>Categoría</th><th>Descripción</th><th>Monto</th><th></th></tr></thead><tbody>{store.expenses.map(original => { const e = effectiveExpense(store, original) ?? original; const voided = !effectiveExpense(store, original); return <tr key={e.id}><td>{e.date}</td><td><span className="category-pill">{e.category}</span></td><td><strong>{e.description}</strong></td><td className="bold-cell">{voided ? "Anulado" : money(e.amount)}</td><td><button className="table-action" onClick={() => { setSelectedExpenseId(e.id); setModal('expenseDetail') }}>Ver detalle</button></td></tr> })}</tbody></table></div>{store.expenses.length === 0 && <Empty text="Aún no hay gastos registrados." />}</div>
        </>}

        {page === 'reports' && <>
          <PageHeading eyebrow="Indicadores y trazabilidad" title="Reportes" subtitle="Ventas y devoluciones se registran en el período en que ocurren." actions={<>{periodPicker}<button className="button button-outline" onClick={() => exportSales(store, 'csv')}><FileDown size={17} /> CSV</button><button className="button button-outline" onClick={() => exportSales(store, 'xlsx')}><FileSpreadsheet size={17} /> Excel</button></>} />
          {period === 'custom' && <div className="date-range"><label>Desde <input className="field" type="date" value={customStart} onChange={e => { setCustomStart(e.target.value); if (e.target.value > customEnd) setCustomEnd(e.target.value) }} /></label><label>Hasta <input className="field" type="date" value={customEnd} min={customStart} onChange={e => setCustomEnd(e.target.value)} /></label></div>}
          <div className="report-grid"><ReportCard label="Ventas netas sin IVA" value={money(report.subtotal)} detail={`IVA separado: ${money(report.vat)}`} /><ReportCard label="Costo neto vendido" value={money(report.cogs)} detail="Costo histórico menos devoluciones" /><ReportCard label="Utilidad bruta" value={money(report.grossProfit)} detail={report.subtotal > 0 ? `${Math.round(report.grossProfit / report.subtotal * 100)}% de margen` : 'Sin ventas netas'} /><ReportCard label="Resultado operativo" value={money(report.operatingResult)} detail={`Después de ${money(report.expenses)} en gastos`} featured /></div>
          <div className="report-two"><section className="panel report-panel"><div className="panel-head"><div><h2>Flujo del período</h2><p>Importes registrados, sin proyección</p></div></div><Flow label="Ventas sin IVA, netas" value={money(report.subtotal)} /><Flow label="IVA neto" value={money(report.vat)} /><Flow label="Cobros menos reembolsos" value={money(report.collected)} /><Flow label="Compras / importaciones" value={money(purchasesNow.filter(p => p.date >= start && (!end || p.date <= end)).reduce((sum, p) => sum + p.total, 0))} /><Flow label="Gastos operativos" value={money(report.expenses)} /><p className="report-note">Las compras se muestran aparte para evitar descontarlas dos veces del resultado calculado con costo vendido.</p></section><section className="panel report-panel"><div className="panel-head"><div><h2>Registro de actividad</h2><p>{remote ? "Últimos cambios del equipo" : "Últimos cambios en este navegador"}</p></div></div><div className="audit-list">{store.audit.slice(0, 12).map(a => <div key={a.id}><span className="audit-dot" /><div><strong>{a.action}</strong><small>{a.detail}{a.actorName ? ` · ${a.actorName}` : ""}</small></div><time>{new Intl.DateTimeFormat('es-EC', { day: '2-digit', month: 'short' }).format(new Date(a.date))}</time></div>)}{store.audit.length === 0 && <Empty text="Sin actividad registrada." />}</div></section></div>
          <div className="report-two"><section className="panel report-panel"><div className="panel-head"><div><h2>Antigüedad por cobrar</h2><p>Días desde la fecha de venta; no equivale a vencimiento.</p></div></div><Flow label="0–30 días" value={money(aging.days0to30)} /><Flow label="31–60 días" value={money(aging.days31to60)} /><Flow label="61–90 días" value={money(aging.days61to90)} /><Flow label="Más de 90 días" value={money(aging.daysOver90)} /></section><section className="panel report-panel"><div className="panel-head"><div><h2>Valoración del inventario</h2><p>Existencias actuales por costo unitario actual.</p></div></div><strong className="valuation-total">{money(valuation)}</strong><p className="report-note">Estimación; aún no distribuye fletes, tributos ni otros costos de importación.</p></section></div>
          <section className="panel profitability-panel"><div className="panel-head"><div><h2>Productos más rentables</h2><p>Precios y costos históricos, sin IVA; devoluciones descontadas.</p></div><select className="period-select" aria-label="Ordenar rentabilidad" value={profitSort} onChange={e => setProfitSort(e.target.value as 'profit' | 'margin' | 'units')}><option value="profit">Ganancia total</option><option value="margin">Margen %</option><option value="units">Unidades</option></select></div><div className="table-scroll"><table><thead><tr><th>Producto</th><th>Unidades netas</th><th>Ventas netas</th><th>Ganancia bruta</th><th>Margen</th></tr></thead><tbody>{profitRows.map(p => <tr key={p.code}><td><div className="two-line"><strong>{p.name}</strong><small>{p.code}</small></div></td><td>{p.units}</td><td>{money(p.revenue)}</td><td className="bold-cell">{money(p.profit)}</td><td>{p.revenue > 0 ? `${Math.round(p.profit / p.revenue * 100)}%` : '—'}</td></tr>)}</tbody></table></div>{profitRows.length === 0 && <Empty text="Sin movimientos comerciales en el período." />}</section>
          <section className="panel profitability-panel"><div className="panel-head"><div><h2>Historial de stock</h2><p>Entradas, ventas, devoluciones y ajustes registrados desde esta versión.</p></div></div><div className="table-scroll"><table><thead><tr><th>Fecha</th><th>Producto</th><th>Cambio</th><th>Saldo</th><th>Motivo</th></tr></thead><tbody>{store.stockMovements.slice(0, 50).map(item => <tr key={item.id}><td>{item.date}</td><td>{item.productCode}</td><td className="bold-cell">{item.delta > 0 ? `+${item.delta}` : item.delta}</td><td>{item.balanceAfter}</td><td>{item.reason}</td></tr>)}</tbody></table></div>{store.stockMovements.length === 0 && <Empty text="Los movimientos nuevos aparecerán aquí." />}</section>
        </>}

        {page === 'sri' && <><PageHeading eyebrow="Módulo reservado" title="SRI" subtitle="Espacio preparado para facturación electrónica cuando se definan los requisitos del negocio." /><div className="sri-card"><div className="sri-icon"><Landmark size={27} /></div><span className="sri-tag">Próximamente · No habilitado</span><h2>Facturación electrónica</h2><p>Este módulo todavía no emite comprobantes, no consulta el SRI y no usa datos fiscales. Se activará solo después de confirmar RUC, tipo de comprobantes, certificados y obligaciones aplicables.</p><div className="sri-divider" /><div className="sri-next"><ShieldCheck size={19} /><span>Sin botones de emisión ni conexión externa en esta versión.</span></div></div></>}

        {page === 'settings' && <><PageHeading eyebrow="Estado del proyecto" title="Configuración" subtitle="Respaldo local y alcance de esta etapa antes de conectar la base de datos." /><div className="settings-grid"><section className="panel settings-panel"><div className="settings-icon"><ShieldCheck size={23} /></div><h2>Datos de este navegador</h2><p>Descarga un respaldo antes de cambiar de equipo o borrar datos. Restaurar un respaldo reemplaza los registros actuales de este navegador.</p><div className="settings-actions"><button className="button button-outline" onClick={() => downloadBackup(store)}><Download size={16} /> Descargar respaldo</button><input ref={backupInput} className="hidden-input" type="file" accept=".json" onChange={importBackup} /><button className="button button-outline" onClick={() => backupInput.current?.click()}><FileUp size={16} /> Restaurar respaldo</button></div><div className="settings-actions" style={{ marginTop: 10 }}><button className="button button-danger" onClick={clearAll}>Borrar datos locales</button></div></section><section className="panel settings-panel"><div className="settings-icon blue"><ChevronDown size={23} /></div><h2>Estado de la implementación</h2><ul className="roadmap"><li><span>Funcional</span><strong>Inventario, varias piezas por venta, cobros, devoluciones, anulaciones, reembolsos, entradas, gastos, reportes y archivos.</strong></li><li><span>Preparado</span><strong>Esquema de base de datos con permisos de lectura y escrituras cerradas hasta implementar operaciones seguras.</strong></li><li><span>Pendiente</span><strong>Conectar servidor, autenticación, permisos, respaldos automáticos y auditoría protegida.</strong></li></ul></section></div><div className="notice-panel"><strong>Alcance fiscal</strong><p>El IVA se muestra separado. No hay emisión electrónica ni conexión SRI. La tasa precargada de ejemplo debe validarse antes de trabajar con datos reales.</p></div></>}
      </div>
    </main>

    {toast && <div className="toast" role="status">{toast}<button onClick={() => setToast('')} aria-label="Cerrar aviso"><X size={16} /></button></div>}
    {modal && <div className="modal-backdrop" onMouseDown={e => { if (e.target === e.currentTarget) setModal(null) }}><div className="modal-card" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div className="modal-header"><div><p className="eyebrow">Torquex</p><h2 id="modal-title">{modal === 'product' ? editingProductId ? 'Editar producto' : 'Nuevo producto' : modal === 'sale' ? 'Nueva venta' : modal === 'saleDetail' ? `Venta ${selectedSale?.number ?? ''}` : modal === 'payment' ? 'Registrar cobro' : modal === 'refund' ? 'Registrar reembolso' : modal === 'return' ? 'Registrar devolución' : modal === 'cancel' ? 'Anular venta' : modal === 'import' ? 'Nueva entrada' : modal === 'importDetail' ? 'Detalle de importación' : modal === 'expense' ? 'Nuevo gasto' : modal === 'expenseDetail' ? 'Detalle del gasto' : modal === 'editExpense' ? 'Corregir o anular gasto' : modal === 'editImport' ? 'Corregir o anular entrada' : modal === 'count' ? 'Conteo de inventario' : modal === 'adjust' ? 'Ajustar stock' : modal === 'catalogPreview' ? 'Vista previa de importación' : modal === 'backupPreview' ? 'Vista previa del respaldo' : confirmAction?.title}</h2></div><button aria-label="Cerrar" onClick={() => setModal(null)}><X size={21} /></button></div>

      {modal === 'product' && <form className="modal-body" onSubmit={saveProduct}><div className="form-grid">
        <Field label="Nombre de la pieza *"><input className="field" required value={productForm.name} onChange={e => setProductForm({ ...productForm, name: e.target.value })} /></Field>
        <Field label="Categoría"><input className="field" value={productForm.category} onChange={e => setProductForm({ ...productForm, category: e.target.value })} /></Field>
        <Field label="Marca"><input className="field" value={productForm.brand} onChange={e => setProductForm({ ...productForm, brand: e.target.value })} /></Field>
        <Field label="Modelo / referencia"><input className="field" value={productForm.model} onChange={e => setProductForm({ ...productForm, model: e.target.value })} /></Field>
        <Field label="Vehículo"><input className="field" value={productForm.vehicle} onChange={e => setProductForm({ ...productForm, vehicle: e.target.value })} /></Field>
        <Field label="Tipo de pieza"><input className="field" value={productForm.partType} onChange={e => setProductForm({ ...productForm, partType: e.target.value })} /></Field>
        <Field label="Compatibilidades (una por línea)" wide><textarea className="field" rows={3} value={productForm.compatibility} onChange={e => setProductForm({ ...productForm, compatibility: e.target.value })} placeholder={'Toyota Hilux 2.4, 2016–2024\nToyota Fortuner 2.4, 2017–2023'} /></Field>
        <div className="compat-editor"><div className="form-section-head"><strong>Compatibilidad estructurada</strong><button type="button" className="table-action" onClick={() => setCompatRows([...compatRows, { id: uid(), brand: '', model: '', engine: '', yearFrom: null, yearTo: null, notes: '' }])}><Plus size={15} /> Vehículo</button></div>{compatRows.map((c, i) => <div className="compat-row" key={c.id}><input className="field" aria-label={`Marca vehículo ${i + 1}`} placeholder="Marca" value={c.brand} onChange={e => setCompatRows(compatRows.map(row => row.id === c.id ? { ...row, brand: e.target.value } : row))} /><input className="field" aria-label={`Modelo vehículo ${i + 1}`} placeholder="Modelo" value={c.model} onChange={e => setCompatRows(compatRows.map(row => row.id === c.id ? { ...row, model: e.target.value } : row))} /><input className="field" aria-label={`Motor ${i + 1}`} placeholder="Motor" value={c.engine} onChange={e => setCompatRows(compatRows.map(row => row.id === c.id ? { ...row, engine: e.target.value } : row))} /><input className="field" aria-label={`Año desde ${i + 1}`} type="number" placeholder="Desde" value={c.yearFrom ?? ''} onChange={e => setCompatRows(compatRows.map(row => row.id === c.id ? { ...row, yearFrom: e.target.value ? Number(e.target.value) : null } : row))} /><input className="field" aria-label={`Año hasta ${i + 1}`} type="number" placeholder="Hasta" value={c.yearTo ?? ''} onChange={e => setCompatRows(compatRows.map(row => row.id === c.id ? { ...row, yearTo: e.target.value ? Number(e.target.value) : null } : row))} /><input className="field" aria-label={`Notas ${i + 1}`} placeholder="Notas" value={c.notes} onChange={e => setCompatRows(compatRows.map(row => row.id === c.id ? { ...row, notes: e.target.value } : row))} /><button type="button" className="icon-action" aria-label={`Quitar vehículo ${i + 1}`} onClick={() => setCompatRows(compatRows.filter(row => row.id !== c.id))}><Trash2 size={16} /></button></div>)}</div>
        <Field label="Stock inicial *"><input className="field" type="number" min="0" step="1" required disabled={!!editingProductId} value={productForm.stock} onChange={e => setProductForm({ ...productForm, stock: e.target.value })} /></Field>
        <Field label="Stock mínimo (opcional)"><input className="field" type="number" min="0" step="1" value={productForm.minStock} onChange={e => setProductForm({ ...productForm, minStock: e.target.value })} /></Field>
        <Field label="Costo unitario *"><input className="field" type="number" min="0" step="0.01" required value={productForm.cost} onChange={e => setProductForm({ ...productForm, cost: e.target.value })} /></Field>
        <Field label="Precio sin IVA *"><input className="field" type="number" min="0" step="0.01" required value={productForm.price} onChange={e => setProductForm({ ...productForm, price: e.target.value })} /></Field>
      </div><p className="form-hint">{editingProductId ? 'Para cambiar existencias usa Ajustar stock. Las ventas previas conservan costo y precio.' : `Se asignará el código ${nextCode(store.products)}.`}</p><ModalActions onCancel={() => setModal(null)} save="Guardar producto" /></form>}

      {modal === 'sale' && <form className="modal-body" onSubmit={saveSale}><div className="form-grid"><Field label="Cliente *" wide><input className="field" required value={saleForm.customer} onChange={e => setSaleForm({ ...saleForm, customer: e.target.value })} placeholder="Nombre o razón social" /></Field><Field label="Fecha *"><input className="field" type="date" required value={saleForm.date} onChange={e => setSaleForm({ ...saleForm, date: e.target.value })} /></Field><Field label="IVA (%) *"><input className="field" type="number" min="0" max="100" step="0.01" required value={saleForm.vatRate} onChange={e => setSaleForm({ ...saleForm, vatRate: e.target.value })} /></Field></div>
        <div className="form-section-head"><strong>Piezas de la venta</strong><button type="button" className="table-action" onClick={() => setSaleItems([...saleItems, blankItem()])}><Plus size={15} /> Agregar pieza</button></div>
        <div className="sale-item-list">{saleItems.map((item, index) => <div className="sale-item" key={item.id}><span className="sale-item-index">{index + 1}</span><select className="field" aria-label={`Producto ${index + 1}`} required value={item.productId} onChange={e => setSaleItems(saleItems.map(row => row.id === item.id ? { ...row, productId: e.target.value } : row))}><option value="">Seleccionar producto</option>{activeProducts.map(p => <option key={p.id} value={p.id} disabled={p.stock < 1}>{p.code} · {p.name} (stock {p.stock})</option>)}</select><input className="field" aria-label={`Cantidad ${index + 1}`} type="number" min="1" step="1" required value={item.quantity} onChange={e => setSaleItems(saleItems.map(row => row.id === item.id ? { ...row, quantity: e.target.value } : row))} /><button type="button" className="icon-action" aria-label={`Quitar pieza ${index + 1}`} disabled={saleItems.length === 1} onClick={() => setSaleItems(saleItems.filter(row => row.id !== item.id))}><Trash2 size={17} /></button></div>)}</div>
        <div className="form-grid" style={{ marginTop: 17 }}><Field label="Cobro inicial"><input className="field" type="number" min="0" step="0.01" value={saleForm.paid} onChange={e => setSaleForm({ ...saleForm, paid: e.target.value })} /></Field></div>
        <div className="form-summary"><Flow label="Subtotal" value={money(saleSubtotalPreview)} /><Flow label="IVA" value={money(saleVatPreview)} /><div className="summary-total"><span>Total</span><strong>{money(saleSubtotalPreview + saleVatPreview)}</strong></div></div><p className="form-hint">La tasa de IVA precargada es ilustrativa y editable. Verifica la tasa aplicable antes de usar datos reales.</p><ModalActions onCancel={() => setModal(null)} save="Registrar venta" />
      </form>}

      {modal === 'saleDetail' && selectedSale && <div className="modal-body"><div className="detail-hero"><span className={`badge ${selectedSale.status === 'cancelled' ? 'badge-muted' : 'badge-ok'}`}>{selectedSale.status === 'cancelled' ? 'Anulada' : 'Activa'}</span><strong>{selectedSale.customer}</strong><small>{selectedSale.number} · {selectedSale.date}{selectedSale.createdByName ? ` · ${selectedSale.createdByName}` : ""}</small></div><div className="detail-section"><h3>Piezas</h3>{selectedSale.lines.map(line => <div className="detail-line" key={line.id}><div><strong>{line.productName}</strong><small>{line.productCode} · {line.quantity} vendidas · {returnedQuantity(store, line.id)} devueltas</small></div><strong>{money(line.total)}</strong></div>)}</div><div className="detail-section"><h3>Importes</h3><Flow label="Subtotal original" value={money(selectedSale.subtotal)} /><Flow label="IVA original" value={money(selectedSale.vatAmount)} /><Flow label="Total original" value={money(selectedSale.total)} /><Flow label="Total después de devoluciones" value={money(netSale(store, selectedSale).total)} /><Flow label="Cobrado menos reembolsos" value={money(netPaid(store, selectedSale.id))} /><Flow label={saleBalance(store, selectedSale) < 0 ? 'Por reembolsar' : 'Por cobrar'} value={money(Math.abs(saleBalance(store, selectedSale)))} /></div><div className="detail-section"><h3>Movimientos</h3>{store.payments.filter(p => p.saleId === selectedSale.id).map(p => <DetailMovement key={p.id} label={`Cobro · ${p.method}`} date={p.date} value={money(p.amount)} />)}{store.returns.filter(r => r.saleId === selectedSale.id).map(r => <DetailMovement key={r.id} label={`Devolución · ${r.quantity} × ${r.productName}`} date={r.date} value={`−${money(r.total)}`} detail={r.reason} />)}{store.refunds.filter(r => r.saleId === selectedSale.id).map(r => <DetailMovement key={r.id} label={`Reembolso · ${r.method}`} date={r.date} value={`−${money(r.amount)}`} detail={r.reason} />)}{!store.payments.some(p => p.saleId === selectedSale.id) && !store.returns.some(r => r.saleId === selectedSale.id) && <p className="form-hint">Sin cobros ni devoluciones.</p>}</div><div className="detail-actions">{saleBalance(store, selectedSale) > 0 && <button className="button button-primary" onClick={() => openPayment(selectedSale)}>Registrar cobro</button>}{saleBalance(store, selectedSale) < 0 && <button className="button button-primary" onClick={() => openRefund(selectedSale)}>Registrar reembolso</button>}{selectedSale.status === 'active' && selectedSale.lines.some(line => line.quantity > returnedQuantity(store, line.id)) && <button className="button button-outline" onClick={() => openReturn(selectedSale)}>Registrar devolución</button>}{selectedSale.status === 'active' && <button className="button button-danger" onClick={() => openCancel(selectedSale)}>Anular venta</button>}</div></div>}

      {modal === 'payment' && selectedSale && <form className="modal-body" onSubmit={savePayment}><p className="form-intro">{selectedSale.number} · {selectedSale.customer}<br />Por cobrar: <strong>{money(Math.max(0, saleBalance(store, selectedSale)))}</strong></p><div className="form-grid"><Field label="Monto *"><input className="field" type="number" min="0.01" step="0.01" required value={paymentForm.amount} onChange={e => setPaymentForm({ ...paymentForm, amount: e.target.value })} /></Field><Field label="Método"><MethodSelect value={paymentForm.method} onChange={method => setPaymentForm({ ...paymentForm, method })} /></Field><Field label="Fecha *"><input className="field" type="date" required value={paymentForm.date} onChange={e => setPaymentForm({ ...paymentForm, date: e.target.value })} /></Field></div><ModalActions onCancel={() => setModal('saleDetail')} save="Guardar cobro" /></form>}
      {modal === 'refund' && selectedSale && <form className="modal-body" onSubmit={saveRefund}><p className="form-intro">{selectedSale.number} · {selectedSale.customer}<br />Por reembolsar: <strong>{money(Math.max(0, -saleBalance(store, selectedSale)))}</strong></p><div className="form-grid"><Field label="Monto *"><input className="field" type="number" min="0.01" step="0.01" required value={refundForm.amount} onChange={e => setRefundForm({ ...refundForm, amount: e.target.value })} /></Field><Field label="Método"><MethodSelect value={refundForm.method} onChange={method => setRefundForm({ ...refundForm, method })} /></Field><Field label="Fecha *"><input className="field" type="date" required value={refundForm.date} onChange={e => setRefundForm({ ...refundForm, date: e.target.value })} /></Field><Field label="Motivo *" wide><textarea className="field" required rows={3} value={refundForm.reason} onChange={e => setRefundForm({ ...refundForm, reason: e.target.value })} /></Field></div><ModalActions onCancel={() => setModal('saleDetail')} save="Guardar reembolso" /></form>}
      {modal === 'return' && selectedSale && <form className="modal-body" onSubmit={saveReturn}><p className="form-intro">{selectedSale.number} · {selectedSale.customer}. La pieza devuelta volverá al stock y su importe se descontará de la venta.</p><div className="form-grid"><Field label="Pieza *" wide><select className="field" required value={returnForm.lineId} onChange={e => setReturnForm({ ...returnForm, lineId: e.target.value, quantity: '1' })}>{selectedSale.lines.map(line => <option key={line.id} value={line.id} disabled={line.quantity <= returnedQuantity(store, line.id)}>{line.productName} · disponibles para devolver: {line.quantity - returnedQuantity(store, line.id)}</option>)}</select></Field><Field label="Cantidad *"><input className="field" type="number" min="1" max={(() => { const line = selectedSale.lines.find(item => item.id === returnForm.lineId); return line ? line.quantity - returnedQuantity(store, line.id) : 1 })()} step="1" required value={returnForm.quantity} onChange={e => setReturnForm({ ...returnForm, quantity: e.target.value })} /></Field><Field label="Fecha *"><input className="field" type="date" required value={returnForm.date} onChange={e => setReturnForm({ ...returnForm, date: e.target.value })} /></Field><Field label="Motivo *" wide><textarea className="field" required rows={3} value={returnForm.reason} onChange={e => setReturnForm({ ...returnForm, reason: e.target.value })} /></Field></div><p className="form-hint">Si ya se cobró más de lo que queda por pagar, aparecerá un saldo por reembolsar.</p><ModalActions onCancel={() => setModal('saleDetail')} save="Registrar devolución" /></form>}
      {modal === 'cancel' && selectedSale && <form className="modal-body" onSubmit={saveCancel}><p className="form-intro">La venta permanecerá en el historial. Se restaurará el stock restante y se mostrará cualquier importe por reembolsar.</p><div className="form-grid"><Field label="Fecha *"><input className="field" type="date" required value={cancelForm.date} onChange={e => setCancelForm({ ...cancelForm, date: e.target.value })} /></Field><Field label="Motivo *" wide><textarea className="field" required rows={3} value={cancelForm.reason} onChange={e => setCancelForm({ ...cancelForm, reason: e.target.value })} /></Field></div><ModalActions onCancel={() => setModal('saleDetail')} save="Continuar anulación" /></form>}

      {modal === 'import' && <form className="modal-body" onSubmit={saveImport}><div className="form-grid"><Field label="Proveedor *" wide><input className="field" required value={importForm.supplier} onChange={e => setImportForm({ ...importForm, supplier: e.target.value })} /></Field><Field label="Producto *" wide><select className="field" required value={importForm.productId} onChange={e => { const p = store.products.find(p => p.id === e.target.value); setImportForm({ ...importForm, productId: e.target.value, unitCost: p ? String(p.cost) : '' }) }}><option value="">Seleccionar producto</option>{activeProducts.map(p => <option key={p.id} value={p.id}>{p.code} · {p.name}</option>)}</select></Field><Field label="Cantidad *"><input className="field" type="number" min="1" step="1" required value={importForm.quantity} onChange={e => setImportForm({ ...importForm, quantity: e.target.value })} /></Field><Field label="Costo unitario *"><input className="field" type="number" min="0" step="0.01" required value={importForm.unitCost} onChange={e => setImportForm({ ...importForm, unitCost: e.target.value })} /></Field><Field label="Fecha *"><input className="field" type="date" required value={importForm.date} onChange={e => setImportForm({ ...importForm, date: e.target.value })} /></Field></div><p className="form-hint">Se sumará el stock y cambiará el costo actual. Los registros anteriores conservan sus costos.</p><ModalActions onCancel={() => setModal(null)} save="Registrar entrada" /></form>}
      {modal === 'importDetail' && selectedImport && <div className="modal-body"><div className="detail-hero"><span className={`badge ${selectedImportVoided ? "badge-muted" : "badge-ok"}`}>{selectedImportVoided ? "Entrada anulada" : "Entrada vigente"}</span><strong>{selectedImport.productName}</strong><small>{selectedImport.productCode} · {selectedImport.date}</small></div><div className="detail-section"><h3>¿Qué fue esta entrada?</h3><p className="detail-copy">{selectedImportVoided ? "Esta entrada fue anulada y su importe ya no se cuenta en reportes. Originalmente se recibieron " : "Se recibieron "} {selectedImport.quantity} unidades de {selectedImport.productName} del proveedor {selectedImport.supplier}. El costo unitario quedó guardado en este registro y el stock del producto aumentó en ese momento.</p><Flow label="Proveedor" value={selectedImport.supplier} /><Flow label="Registró" value={selectedImport.createdByName ?? "Registro anterior"} /><Flow label="Cantidad" value={`${selectedImport.quantity} unidades`} /><Flow label="Costo unitario" value={money(selectedImport.unitCost)} /><Flow label="Costo total" value={money(selectedImport.total)} /></div><div className="detail-section"><h3>Historial de correcciones</h3>{store.purchaseRevisions.filter(r => r.purchaseId === selectedImport.id).map(r => <DetailMovement key={r.id} label={r.action === 'void' ? 'Anulación' : 'Corrección'} date={r.recordedAt.slice(0, 10)} value={r.reason} detail={`${r.before.quantity} → ${r.after?.quantity ?? 0} unidades`} />)}</div><div className="detail-actions">{!selectedImportVoided && <button className="button button-outline" onClick={openEditImport}>Corregir o anular</button>}<button className="button button-primary" onClick={() => setModal(null)}>Cerrar</button></div></div>}

      {modal === 'expense' && <form className="modal-body" onSubmit={saveExpense}><div className="form-grid"><Field label="Categoría *"><input className="field" required value={expenseForm.category} onChange={e => setExpenseForm({ ...expenseForm, category: e.target.value })} placeholder="Logística, operación…" /></Field><Field label="Fecha *"><input className="field" type="date" required value={expenseForm.date} onChange={e => setExpenseForm({ ...expenseForm, date: e.target.value })} /></Field><Field label="Descripción *" wide><textarea className="field" required rows={3} value={expenseForm.description} onChange={e => setExpenseForm({ ...expenseForm, description: e.target.value })} placeholder="¿Qué se pagó y por qué?" /></Field><Field label="Monto *"><input className="field" type="number" min="0.01" step="0.01" required value={expenseForm.amount} onChange={e => setExpenseForm({ ...expenseForm, amount: e.target.value })} /></Field></div><ModalActions onCancel={() => setModal(null)} save="Registrar gasto" /></form>}
      {modal === 'expenseDetail' && selectedExpense && <div className="modal-body"><div className="detail-hero"><span className={`badge ${selectedExpenseVoided ? "badge-muted" : "badge-warning"}`}>{selectedExpenseVoided ? "Gasto anulado" : selectedExpense.category}</span><strong>{selectedExpense.description}</strong><small>{selectedExpense.date}</small></div><div className="detail-section"><h3>¿Qué fue este gasto?</h3><p className="detail-copy">{selectedExpenseVoided ? "Este gasto fue anulado y ya no se cuenta en reportes. Originalmente se registró" : "Este egreso se registró"} en la categoría {selectedExpense.category}. Su importe se descuenta del resultado operativo del período correspondiente.</p><Flow label="Fecha" value={selectedExpense.date} /><Flow label="Registró" value={selectedExpense.createdByName ?? "Registro anterior"} /><Flow label="Categoría" value={selectedExpense.category} /><Flow label="Concepto" value={selectedExpense.description} /><Flow label="Monto" value={money(selectedExpense.amount)} /></div><div className="detail-section"><h3>Historial de correcciones</h3>{store.expenseRevisions.filter(r => r.expenseId === selectedExpense.id).map(r => <DetailMovement key={r.id} label={r.action === 'void' ? 'Anulación' : 'Corrección'} date={r.recordedAt.slice(0, 10)} value={r.reason} detail={`${money(r.before.amount)} → ${money(r.after?.amount ?? 0)}`} />)}</div><div className="detail-actions">{!selectedExpenseVoided && <button className="button button-outline" onClick={openEditExpense}>Corregir o anular</button>}<button className="button button-primary" onClick={() => setModal(null)}>Cerrar</button></div></div>}

      {modal === 'adjust' && selectedProduct && <form className="modal-body" onSubmit={saveAdjustment}><p className="form-intro">{selectedProduct.code} · {selectedProduct.name}<br />Stock actual: <strong>{selectedProduct.stock} unidades</strong></p><div className="form-grid"><Field label="Nuevo stock *"><input className="field" type="number" min="0" step="1" required value={adjustForm.stock} onChange={e => setAdjustForm({ ...adjustForm, stock: e.target.value })} /></Field><Field label="Motivo *" wide><textarea className="field" required rows={3} value={adjustForm.reason} onChange={e => setAdjustForm({ ...adjustForm, reason: e.target.value })} /></Field></div><ModalActions onCancel={() => setModal(null)} save="Continuar ajuste" /></form>}

      {modal === 'editExpense' && selectedExpense && <form className="modal-body" onSubmit={saveExpenseRevision}><div className="form-grid"><Field label="Categoría *"><input className="field" required value={expenseForm.category} onChange={e => setExpenseForm({ ...expenseForm, category: e.target.value })} /></Field><Field label="Fecha *"><input className="field" type="date" required value={expenseForm.date} onChange={e => setExpenseForm({ ...expenseForm, date: e.target.value })} /></Field><Field label="Descripción *" wide><textarea className="field" required value={expenseForm.description} onChange={e => setExpenseForm({ ...expenseForm, description: e.target.value })} /></Field><Field label="Monto *"><input className="field" type="number" min="0.01" step="0.01" required value={expenseForm.amount} onChange={e => setExpenseForm({ ...expenseForm, amount: e.target.value })} /></Field><Field label="Motivo del cambio *" wide><textarea className="field" required value={revisionReason} onChange={e => setRevisionReason(e.target.value)} /></Field></div><div className="modal-actions"><button className="button button-outline" type="button" onClick={() => setModal('expenseDetail')}>Volver</button><button className="button button-danger" type="button" onClick={voidExpense}>Anular gasto</button><button className="button button-primary" type="submit">Guardar corrección</button></div></form>}
      {modal === 'editImport' && selectedImport && <form className="modal-body" onSubmit={saveImportRevision}><p className="form-intro">{selectedImport.productCode} · {selectedImport.productName}. El producto no se cambia; la diferencia de cantidad ajustará su stock.</p><div className="form-grid"><Field label="Proveedor *" wide><input className="field" required value={importForm.supplier} onChange={e => setImportForm({ ...importForm, supplier: e.target.value })} /></Field><Field label="Fecha *"><input className="field" type="date" required value={importForm.date} onChange={e => setImportForm({ ...importForm, date: e.target.value })} /></Field><Field label="Cantidad *"><input className="field" type="number" min="1" step="1" required value={importForm.quantity} onChange={e => setImportForm({ ...importForm, quantity: e.target.value })} /></Field><Field label="Costo unitario *"><input className="field" type="number" min="0" step="0.01" required value={importForm.unitCost} onChange={e => setImportForm({ ...importForm, unitCost: e.target.value })} /></Field><Field label="Motivo del cambio *" wide><textarea className="field" required value={revisionReason} onChange={e => setRevisionReason(e.target.value)} /></Field></div><div className="modal-actions"><button className="button button-outline" type="button" onClick={() => setModal('importDetail')}>Volver</button><button className="button button-danger" type="button" onClick={voidImport}>Anular entrada</button><button className="button button-primary" type="submit">Guardar corrección</button></div></form>}
      {modal === 'count' && <form className="modal-body" onSubmit={saveCount}><p className="form-intro">Escribe solo los productos que contaste físicamente. Los espacios en blanco quedan sin cambio.</p><div className="form-grid"><Field label="Fecha *"><input className="field" type="date" required value={countDate} onChange={e => setCountDate(e.target.value)} /></Field><Field label="Motivo *" wide><textarea className="field" required value={countReason} onChange={e => setCountReason(e.target.value)} placeholder="Conteo mensual, revisión de bodega…" /></Field></div><div className="count-list">{activeProducts.map(p => <label key={p.id}><span><strong>{p.code} · {p.name}</strong><small>En sistema: {p.stock}</small></span><input className="field" type="number" min="0" step="1" aria-label={`Cantidad contada ${p.name}`} value={countValues[p.id] ?? ''} onChange={e => setCountValues({ ...countValues, [p.id]: e.target.value })} placeholder="Contado" /></label>)}</div><ModalActions onCancel={() => setModal(null)} save="Registrar conteo" /></form>}
      {modal === 'catalogPreview' && catalogPreview && <div className="modal-body"><p className="form-intro"><strong>{catalogPreview.filename}</strong><br />{catalogPreview.products.length} productos nuevos · {numeric(catalogPreview.products.reduce((sum, p) => sum + p.stock, 0))} unidades iniciales.</p><div className="preview-list">{catalogPreview.products.slice(0, 8).map(p => <div key={p.id}><strong>{p.code} · {p.name}</strong><span>{p.brand} {p.model} · stock {p.stock}</span></div>)}{catalogPreview.products.length > 8 && <p>Y {catalogPreview.products.length - 8} productos más…</p>}</div><p className="form-hint">No se reemplazará ningún producto. Revisa nombres y cantidades antes de continuar.</p><div className="modal-actions"><button className="button button-outline" onClick={() => setModal(null)}>Cancelar</button><button className="button button-primary" onClick={confirmCatalog}>Agregar productos</button></div></div>}
      {modal === 'backupPreview' && backupPreview && <div className="modal-body"><p className="form-intro">Este respaldo contiene {backupPreview.products.length} productos, {backupPreview.sales.length} ventas, {backupPreview.purchases.length} entradas y {backupPreview.expenses.length} gastos.</p><p className="form-hint">Restaurar reemplazará todos los datos actuales de este navegador. Descarga primero un respaldo de los datos actuales si quieres conservarlos.</p><div className="modal-actions"><button className="button button-outline" onClick={() => setModal(null)}>Cancelar</button><button className="button button-primary" onClick={confirmBackup}>Continuar restauración</button></div></div>}
      {modal === 'confirm' && confirmAction && <div className="modal-body"><p className="form-intro">{confirmAction.detail}</p><div className="confirm-list">{['Revisé los datos y el alcance del cambio.', 'Entiendo cómo afectará el inventario o los registros locales.', 'Autorizo este cambio en el prototipo.'].map((label, index) => <label key={label}><input type="checkbox" checked={confirmChecks[index]} onChange={e => setConfirmChecks(confirmChecks.map((value, i) => i === index ? e.target.checked : value))} /><span>{label}</span></label>)}</div><p className="form-hint">Estas confirmaciones reducen errores accidentales. Los permisos reales requieren conexión a un servidor.</p><div className="modal-actions"><button className="button button-outline" onClick={() => setModal(null)}>Cancelar</button><button className="button button-primary" disabled={!confirmChecks.every(Boolean)} onClick={() => confirmAction.run()}>Confirmar cambio</button></div></div>}
    </div></div>}
  </div>
}

function PageHeading({ eyebrow, title, subtitle, actions }: { eyebrow: string; title: string; subtitle: string; actions?: ReactNode }) { return <div className="page-heading"><div><p className="eyebrow">{eyebrow}</p><h1>{title}</h1><p className="page-subtitle">{subtitle}</p></div>{actions && <div className="heading-actions">{actions}</div>}</div> }
function Metric({ label, value, detail, icon, accent }: { label: string; value: string; detail: string; icon: ReactNode; accent: string }) { return <div className={`metric metric-${accent}`}><div className="metric-top"><span>{label}</span><span className="metric-icon">{icon}</span></div><strong>{value}</strong><small>{detail}</small></div> }
function MiniMetric({ label, value }: { label: string; value: string }) { return <div><span>{label}</span><strong>{value}</strong></div> }
function ReportCard({ label, value, detail, featured }: { label: string; value: string; detail: string; featured?: boolean }) { return <div className={`report-card ${featured ? 'featured' : ''}`}><span>{label}</span><strong>{value}</strong><small>{detail}</small></div> }
function QuickAction({ icon, title, detail, onClick }: { icon: ReactNode; title: string; detail: string; onClick: () => void }) { return <button onClick={onClick}><span className="quick-icon">{icon}</span><span><strong>{title}</strong><small>{detail}</small></span><ArrowRight size={18} /></button> }
function Flow({ label, value }: { label: string; value: string }) { return <div className="flow-row"><span>{label}</span><strong>{value}</strong></div> }
function Field({ label, children, wide }: { label: string; children: ReactNode; wide?: boolean }) { return <label className={`form-field ${wide ? 'wide' : ''}`}><span>{label}</span>{children}</label> }
function ModalActions({ onCancel, save }: { onCancel: () => void; save: string }) { return <div className="modal-actions"><button className="button button-outline" type="button" onClick={onCancel}>Cancelar</button><button className="button button-primary" type="submit">{save}</button></div> }
function MethodSelect({ value, onChange }: { value: string; onChange: (value: string) => void }) { return <select className="field" value={value} onChange={e => onChange(e.target.value)}><option>Transferencia</option><option>Efectivo</option><option>Tarjeta</option><option>Otro</option></select> }
function DetailMovement({ label, date, value, detail }: { label: string; date: string; value: string; detail?: string }) { return <div className="detail-line"><div><strong>{label}</strong><small>{date}{detail ? ` · ${detail}` : ''}</small></div><strong>{value}</strong></div> }
function Empty({ text }: { text: string }) { return <div className="empty-state"><Package size={24} /><p>{text}</p></div> }

export default App
